<?php require_once __DIR__.'/../../helpers/bootstrap.php'; layout_start('Laporan'); $rows=db()->query("SELECT c.name category,COUNT(p.id) total_products,COALESCE(SUM(p.stock),0) total_stock,COALESCE(AVG(p.price),0) average_price FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id,c.name ORDER BY c.name")->fetchAll(); ?><h1>Laporan inventory</h1><table><tr><th>Kategori</th><th>Produk</th><th>Total stok</th><th>Rata-rata harga</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['category'])?></td><td><?=e($r['total_products'])?></td><td><?=e($r['total_stock'])?></td><td>Rp <?=number_format($r['average_price'],0,',','.')?></td></tr><?php endforeach?></table><?php layout_end();?>